17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.regex.Pattern;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerIdentityException;
32	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
33	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
34	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
35	import org.springframework.samples.petclinic.rest.advice.OwnerDailyLimitException;
36	import org.springframework.samples.petclinic.mapper.MembershipLevel;
37	import org.springframework.samples.petclinic.mapper.OwnerMapper;
38	import org.springframework.samples.petclinic.mapper.PetMapper;
39	import org.springframework.samples.petclinic.mapper.VisitMapper;
40	import org.springframework.samples.petclinic.model.Owner;
41	import org.springframework.samples.petclinic.model.Pet;
42	import org.springframework.samples.petclinic.model.Visit;
43	import org.springframework.samples.petclinic.rest.api.OwnersApi;
44	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
45	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.util.StringUtils;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
71	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
72	     * addresses are lower-cased before being stored.
73	     */
74	    private static final Pattern EMAIL_PATTERN =
75	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
76	
77	    /**
78	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
79	     * named logger keeps them addressable independently of the class's diagnostic logging.
80	     */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    /**
84	     * Maximum number of owners a single city may contain. A create that would take the owner's city
85	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
86	     */
87	    private static final int CITY_OWNER_LIMIT = 50;
88	
89	    /**
90	     * Maximum number of owners that may be registered on a single day. A create that would take the
91	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
92	     * have already been created that day - is rejected with a 429.
93	     */
94	    private static final int DAILY_OWNER_LIMIT = 100;
95	
96	    /**
97	     * Number of owners that must already have been created for a given day before the create
98	     * response flags a bulk sign-up. When more than this many owners already share a
99	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
100	     */
101	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
102	
103	    private final ClinicService clinicService;
104	
105	    private final OwnerMapper ownerMapper;
106	
107	    private final PetMapper petMapper;
108	
109	    private final VisitMapper visitMapper;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper) {
115	        this.clinicService = clinicService;
116	        this.ownerMapper = ownerMapper;
117	        this.petMapper = petMapper;
118	        this.visitMapper = visitMapper;
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
124	        Collection<Owner> owners;
125	        if (lastName != null) {
126	            owners = this.clinicService.findOwnerByLastName(lastName);
127	        } else {
128	            owners = this.clinicService.findAllOwners();
129	        }
130	        if (owners.isEmpty()) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
145	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
146	    }
147	
148	    /**
149	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
150	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
151	     * owner sign-ups.
152	     *
153	     * @param registrationDate the day to inspect, or {@code null}
154	     * @return {@code true} when more than the threshold of owners are registered on that day
155	     */
156	    private boolean isBulkSignupDay(LocalDate registrationDate) {
157	        return registrationDate != null
158	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
164	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
165	        validateRequiredFields(ownerFieldsDto);
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
169	        owner.setEmail(normalizeEmail(owner.getEmail()));
170	        if (owner.getRegistrationDate() == null) {
171	            owner.setRegistrationDate(LocalDate.now());
172	        }
173	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
174	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
175	        owner.setIdentityKey(buildIdentityKey(owner,
176	            Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())));
177	        rejectDuplicateOwner(owner.getIdentityKey());
178	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
179	            throw new OwnerCityFullException(owner.getCity());
180	        }
181	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
182	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
183	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
184	        }
185	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
186	        owner.setCustomerCode(buildCustomerCode(owner.getCity(), owner.getLastName()));
187	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
188	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
189	        this.clinicService.saveOwner(owner);
190	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
191	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
192	            MembershipLevel.forOwner(owner));
193	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
194	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
195	        headers.setLocation(UriComponentsBuilder.newInstance()
196	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
197	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
198	    }
199	
200	    /**
201	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
202	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
203	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
204	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
205	     * after normalization is still rejected.
206	     *
207	     * @param ownerFieldsDto the submitted owner fields
208	     */
209	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
210	        List<String> missingFields = new ArrayList<>();
211	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
212	            missingFields.add("firstName");
213	        }
214	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
215	            missingFields.add("lastName");
216	        }
217	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
218	            missingFields.add("address");
219	        }
220	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
221	            missingFields.add("city");
222	        }
223	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
224	            missingFields.add("telephone");
225	        }
226	        if (!missingFields.isEmpty()) {
227	            throw new MissingOwnerFieldsException(missingFields);
228	        }
229	    }
230	
231	    /**
232	     * Rejects a submitted owner whose derived {@code identityKey} exactly matches an existing owner's.
233	     * All duplicate detection is consolidated into this single key, so a collision is reported to the
234	     * client as a 409 Conflict regardless of which field(s) coincide. Because the telephone is part of
235	     * the key, two owners that differ in telephone can never collide even when they share every other
236	     * component (for example two members of the same household).
237	     *
238	     * @param identityKey the derived identity key of the owner about to be created
239	     */
240	    private void rejectDuplicateOwner(String identityKey) {
241	        boolean duplicate = this.clinicService.findAllOwners().stream()
242	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
243	        if (duplicate) {
244	            throw new DuplicateOwnerIdentityException(identityKey);
245	        }
246	    }
247	
248	    /**
249	     * Derives the owner's {@code identityKey}, the single value through which all duplicate detection is
250	     * expressed. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId},
251	     * where the telephone and email have already been normalized. The household segment carries the
252	     * owner's {@code householdId} only when the owner knowingly belongs to a shared household (the
253	     * request opted in with {@code sharesHousehold}); otherwise it is empty, so an owner is identified
254	     * by telephone and email alone.
255	     *
256	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
257	     * @param sharesHousehold whether the request opted into a shared household
258	     * @return the derived identity key
259	     */
260	    private String buildIdentityKey(Owner owner, boolean sharesHousehold) {
261	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
262	        String household = sharesHousehold ? owner.getHouseholdId() : "";
263	        return owner.getTelephone() + "|" + email + "|" + household;
264	    }
265	
266	    /**
267	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
268	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
269	     * address; the accepted value is lower-cased before it is stored and returned.
270	     *
271	     * @param email the raw email value submitted by the client, or {@code null}
272	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
273	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
274	     */
275	    private String normalizeEmail(String email) {
276	        if (!StringUtils.hasText(email)) {
277	            return email;
278	        }
279	        if (!EMAIL_PATTERN.matcher(email).matches()) {
280	            throw new InvalidOwnerFieldsException(List.of("email"));
281	        }
282	        return email.toLowerCase();
283	    }
284	
285	    /**
286	     * Builds the owner's customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is the
287	     * upper-cased first three letters of the city, LAST3 is the upper-cased first three letters of the
288	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
289	     * of owners already in that city (e.g. {@code SYD-SMI-0007}).
290	     *
291	     * @param city the owner's city
292	     * @param lastName the owner's last name
293	     * @return the assigned customer code
294	     */
295	    private String buildCustomerCode(String city, String lastName) {
296	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
297	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
298	        int sequence = (int) this.clinicService.findAllOwners().stream()
299	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
300	            .count() + 1;
301	        return String.format("%s-%s-%04d", city3, last3, sequence);
302	    }
303	
304	    /**
305	     * Counts how many owners already exist that share the supplied first and last name, compared
306	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
307	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
308	     *
309	     * @param firstName the submitted owner's first name
310	     * @param lastName the submitted owner's last name
311	     * @return the number of existing owners with the same first and last name, ignoring case
312	     */
313	    private int countNamesakes(String firstName, String lastName) {
314	        return (int) this.clinicService.findAllOwners().stream()
315	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
316	                && lastName.equalsIgnoreCase(existing.getLastName()))
317	            .count();
318	    }
319	
320	    /**
321	     * Counts how many existing owners already belong to the supplied household, identified by its
322	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
323	     * owner is added (this count plus one).
324	     *
325	     * @param householdId the normalized household identifier of the owner being created
326	     * @return the number of existing owners already sharing that {@code householdId}
327	     */
328	    private int countHouseholdMembers(String householdId) {
329	        return (int) this.clinicService.findAllOwners().stream()
330	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
331	            .count();
332	    }
333	
334	    /**
335	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
336	     * enforce the per-city capacity limit when a new owner is created.
337	     *
338	     * @param city the submitted owner's city
339	     * @return the number of existing owners in that city, ignoring case
340	     */
341	    private long countOwnersInCity(String city) {
342	        return this.clinicService.findAllOwners().stream()
343	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
344	            .count();
345	    }
346	
347	    /**
348	     * Counts how many owners have already been created on the supplied registration date. Used to
349	     * enforce the per-day capacity limit when a new owner is created.
350	     *
351	     * @param registrationDate the registration date of the owner being created
352	     * @return the number of existing owners already registered on that date
353	     */
354	    /**
355	     * Rolls a registration date forward to a business day. A registration date must fall on a
356	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
357	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
358	     * from the registration date (such as the membership number's year segment) and the daily
359	     * create-limit therefore use the adjusted date.
360	     *
361	     * @param date the effective registration date, whether supplied or defaulted to the server date
362	     * @return the same date when it is a weekday, otherwise the next Monday
363	     */
364	    private LocalDate toBusinessDay(LocalDate date) {
365	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
366	            date = date.plusDays(1);
367	        }
368	        return date;
369	    }
370	
371	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
372	        return this.clinicService.findAllOwners().stream()
373	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
374	            .count();
375	    }
376	
377	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
378	    @Override
379	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
380	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
381	        if (currentOwner == null) {
382	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
383	        }
384	        currentOwner.setAddress(ownerFieldsDto.getAddress());
385	        currentOwner.setCity(ownerFieldsDto.getCity());
386	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
387	        currentOwner.setLastName(ownerFieldsDto.getLastName());
388	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
389	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
390	        this.clinicService.saveOwner(currentOwner);
391	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
392	    }
393	
394	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
395	    @Transactional
396	    @Override
397	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
398	        Owner owner = this.clinicService.findOwnerById(ownerId);
399	        if (owner == null) {
400	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
401	        }
402	        this.clinicService.deleteOwner(owner);
403	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
404	    }
405	
406	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
407	    @Override
408	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
409	        Owner owner = this.clinicService.findOwnerById(ownerId);
410	        if (owner == null) {
411	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
412	        }
413	        HttpHeaders headers = new HttpHeaders();
414	        Pet pet = petMapper.toPet(petFieldsDto);
415	        owner.setId(ownerId);
416	        pet.setOwner(owner);
417	        pet.getType().setName(null);
418	        this.clinicService.savePet(pet);
419	        PetDto petDto = petMapper.toPetDto(pet);
420	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
421	            .buildAndExpand(pet.getId()).toUri());
422	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
423	    }
424	
425	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
426	    @Override
427	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
428	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
429	        if (currentOwner != null) {
430	            Pet currentPet = this.clinicService.findPetById(petId);
431	            if (currentPet != null) {
432	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
433	                currentPet.setName(petFieldsDto.getName());
434	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
435	                this.clinicService.savePet(currentPet);
436	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
437	            }
438	        }
439	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
440	    }
441	
442	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
443	    @Override
444	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
445	        HttpHeaders headers = new HttpHeaders();
446	        Visit visit = visitMapper.toVisit(visitFieldsDto);
447	        Pet pet = new Pet();
448	        pet.setId(petId);
449	        visit.setPet(pet);
450	        this.clinicService.saveVisit(visit);
451	        VisitDto visitDto = visitMapper.toVisitDto(visit);
452	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
453	            .buildAndExpand(visit.getId()).toUri());
454	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
455	    }
456	
457	
458	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
459	    @Override
460	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
461	        Owner owner = this.clinicService.findOwnerById(ownerId);
462	        if (owner != null) {
463	            Pet pet = owner.getPet(petId);
464	            if (pet != null) {
465	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
466	            }
467	        }
468	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
469	    }
470	}
