161	
162	    protected void setPetsInternal(Set<Pet> pets) {
163	        this.pets = pets;
164	    }
165	
166	    public List<Pet> getPets() {
167	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
168	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
169	        return Collections.unmodifiableList(sortedPets);
170	    }
171	
172	    public void setPets(List<Pet> pets) {
173	        this.pets = new HashSet<>(pets);
174	    }
